import { getSP } from "../../../../services/SPService/spservice";
import { ApiResponse } from "../../../../models/apimodels";
import { ICommonService } from "../CommonServices/ICommonService";
export type AutoCompleteItem = {
  key: number;
  text: string;
};

class CommonService implements ICommonService {

  public async getUserGuidByEmail(
    email: string
  ): Promise<ApiResponse<AutoCompleteItem | null>> {

    console.log("🟢 [CommonService] getUserGuidByEmail called with:", email);

    try {

      const sp = getSP();
      console.log("🟢 [CommonService] SP instance:", sp);

      const user = await sp.web.siteUsers.getByEmail(email)();

      console.log("🟢 [CommonService] SharePoint User:", user);

      const userData: AutoCompleteItem = {
        key: user.Id,
        text: user.Title
      };

      console.log("🟢 [CommonService] Processed User Data:", userData);

      return {
        data: userData,
        status: 200,
        message: "User fetched successfully"
      };

    } catch (error) {

      console.error("❌ [CommonService] Error fetching user by email:", error);

      return {
        data: null,
        status: 500,
        message: "Error fetching user"
      };
    }
  }

}

export default new CommonService();